use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, Duration};

use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

// Kerberos ticket delegation flags
const TKT_FLG_FORWARDABLE: u32 = 0x40000000;
const TKT_FLG_FORWARDED: u32 = 0x20000000;
const TKT_FLG_PROXIABLE: u32 = 0x10000000;
const TKT_FLG_OK_AS_DELEGATE: u32 = 0x04000000;

#[derive(Clone, Debug)]
pub struct KerberosTicket {
    pub client_principal: String,
    pub service_principal: String,
    pub flags: u32,
    pub auth_time: u64,
    pub end_time: u64,
    pub renew_till: u64,
    pub session_key: Vec<u8>,
    pub enc_part: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct DelegationContext {
    pub source_realm: String,
    pub target_service: String,
    pub constrained: bool,
    pub allowed_services: Vec<String>,
    pub protocol_transition: bool,
}

pub struct TicketCache {
    tickets: Arc<Mutex<HashMap<String, KerberosTicket>>>,
    delegation_contexts: Arc<Mutex<HashMap<String, DelegationContext>>>,
}

impl TicketCache {
    pub fn new() -> Self {
        TicketCache {
            tickets: Arc::new(Mutex::new(HashMap::new())),
            delegation_contexts: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn store_ticket(&self, principal: &str, ticket: KerberosTicket) {
        let mut cache = self.tickets.lock().unwrap();
        cache.insert(principal.to_string(), ticket);
    }

    pub fn get_ticket(&self, principal: &str) -> Option<KerberosTicket> {
        let cache = self.tickets.lock().unwrap();
        cache.get(principal).cloned()
    }

    pub fn store_delegation_ctx(&self, session_id: &str, ctx: DelegationContext) {
        let mut contexts = self.delegation_contexts.lock().unwrap();
        contexts.insert(session_id.to_string(), ctx);
    }

    pub fn get_delegation_ctx(&self, session_id: &str) -> Option<DelegationContext> {
        let contexts = self.delegation_contexts.lock().unwrap();
        contexts.get(session_id).cloned()
    }
}

pub fn validate_delegation_request(
    ticket: &KerberosTicket,
    delegation_ctx: &DelegationContext,
    target_service: &str,
) -> Result<bool, String> {
    // Check ticket hasn't expired
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_secs();
    if now > ticket.end_time {
        return Err("Ticket expired".to_string());
    }

    // Validate delegation flags on the ticket
    if !check_delegation_flags(ticket.flags, delegation_ctx) {
        return Err("Delegation flags insufficient".to_string());
    }

    // For constrained delegation, verify target is in allowed list
    if delegation_ctx.constrained {
        if !is_service_allowed(target_service, &delegation_ctx.allowed_services) {
            return Err("Target service not in constrained delegation list".to_string());
        }
    }

    Ok(true)
}

fn check_delegation_flags(flags: u32, ctx: &DelegationContext) -> bool {
    // Protocol transition (S4U2Self) still requires forwardable flag
    // to prevent abuse via non-forwardable evidence tickets
    if ctx.protocol_transition {
        return (flags & TKT_FLG_FORWARDABLE) != 0;
    }

    // Standard constrained delegation requires forwardable ticket
    if ctx.constrained {
        return (flags & TKT_FLG_FORWARDABLE) != 0;
    }

    // Unconstrained delegation - check forwarded or forwardable
    (flags & (TKT_FLG_FORWARDABLE | TKT_FLG_FORWARDED)) != 0
}

fn is_service_allowed(target: &str, allowed: &Vec<String>) -> bool {
    // Normalize service principal names for comparison
    let target_normalized = normalize_spn(target);
    for svc in allowed {
        let allowed_normalized = normalize_spn(svc);
        if target_normalized == allowed_normalized {
            return true;
        }
    }
    false
}

fn normalize_spn(spn: &str) -> String {
    // Normalize: lowercase, strip trailing dots from hostnames
    let parts: Vec<&str> = spn.splitn(2, '/').collect();
    if parts.len() == 2 {
        let service_class = parts[0].to_lowercase();
        let hostname = parts[1].to_lowercase().trim_end_matches('.').to_string();
        format!("{}/{}", service_class, hostname)
    } else {
        spn.to_lowercase()
    }
}

pub fn perform_s4u2proxy(
    cache: &TicketCache,
    client_principal: &str,
    service_principal: &str,
    session_id: &str,
) -> Result<KerberosTicket, String> {
    let evidence_ticket = cache.get_ticket(client_principal)
        .ok_or("No evidence ticket found")?;

    let delegation_ctx = cache.get_delegation_ctx(session_id)
        .ok_or("No delegation context")?;

    // Validate the delegation is permitted
    validate_delegation_request(&evidence_ticket, &delegation_ctx, service_principal)?;

    // Issue delegated ticket (simulated KDC response)
    let delegated_ticket = KerberosTicket {
        client_principal: client_principal.to_string(),
        service_principal: service_principal.to_string(),
        flags: evidence_ticket.flags | TKT_FLG_FORWARDED,
        auth_time: evidence_ticket.auth_time,
        end_time: evidence_ticket.end_time,
        renew_till: evidence_ticket.renew_till,
        session_key: derive_session_key(&evidence_ticket.session_key, service_principal),
        enc_part: encrypt_ticket_part(&evidence_ticket, service_principal),
    };

    Ok(delegated_ticket)
}

fn derive_session_key(parent_key: &[u8], service: &str) -> Vec<u8> {
    // Cryptographic key derivation using HMAC-SHA256 keyed by the parent key.
    // This replaces the previous non-cryptographic DefaultHasher (SipHash) usage
    // and produces a full 32-byte key.
    let mut mac = HmacSha256::new_from_slice(parent_key)
        .expect("HMAC accepts keys of any size");
    mac.update(b"kerberos-delegation-session-key-v1");
    mac.update(service.as_bytes());
    mac.finalize().into_bytes().to_vec()
}

fn encrypt_ticket_part(ticket: &KerberosTicket, target: &str) -> Vec<u8> {
    // Authenticated encryption for the delegated ticket enc-part.
    // Derive independent encryption and MAC keys from the session key material,
    // generate a keystream via HMAC-SHA256 in counter mode, then append an
    // HMAC-SHA256 authentication tag over the ciphertext.
    let base_key = derive_session_key(&ticket.session_key, target);

    // Derive separate encryption and MAC keys.
    let enc_key = {
        let mut mac = HmacSha256::new_from_slice(&base_key)
            .expect("HMAC accepts keys of any size");
        mac.update(b"enc");
        mac.finalize().into_bytes().to_vec()
    };
    let mac_key = {
        let mut mac = HmacSha256::new_from_slice(&base_key)
            .expect("HMAC accepts keys of any size");
        mac.update(b"mac");
        mac.finalize().into_bytes().to_vec()
    };

    let plaintext = format!("{}|{}|{}", ticket.client_principal, target, ticket.end_time);
    let plaintext_bytes = plaintext.as_bytes();

    // Generate keystream in counter mode using HMAC-SHA256.
    let mut keystream = Vec::with_capacity(plaintext_bytes.len());
    let mut counter: u64 = 0;
    while keystream.len() < plaintext_bytes.len() {
        let mut mac = HmacSha256::new_from_slice(&enc_key)
            .expect("HMAC accepts keys of any size");
        mac.update(&counter.to_le_bytes());
        keystream.extend_from_slice(&mac.finalize().into_bytes());
        counter += 1;
    }

    let mut ciphertext: Vec<u8> = plaintext_bytes
        .iter()
        .zip(keystream.iter())
        .map(|(p, k)| p ^ k)
        .collect();

    // Compute authentication tag over the ciphertext (encrypt-then-MAC).
    let tag = {
        let mut mac = HmacSha256::new_from_slice(&mac_key)
            .expect("HMAC accepts keys of any size");
        mac.update(&ciphertext);
        mac.finalize().into_bytes().to_vec()
    };

    ciphertext.extend_from_slice(&tag);
    ciphertext
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_constrained_delegation_allows_listed_service() {
        let cache = TicketCache::new();
        let ticket = KerberosTicket {
            client_principal: "user@REALM.COM".to_string(),
            service_principal: "http/frontend.realm.com".to_string(),
            flags: TKT_FLG_FORWARDABLE,
            auth_time: 1700000000,
            end_time: 1700086400,
            renew_till: 1700604800,
            session_key: vec![0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08],
            enc_part: vec![0xAA, 0xBB],
        };
        cache.store_ticket("user@REALM.COM", ticket);

        let ctx = DelegationContext {
            source_realm: "REALM.COM".to_string(),
            target_service: "mssql/db.realm.com".to_string(),
            constrained: true,
            allowed_services: vec!["mssql/db.realm.com".to_string()],
            protocol_transition: false,
        };
        cache.store_delegation_ctx("sess-001", ctx);

        let result = perform_s4u2proxy(&cache, "user@REALM.COM", "mssql/db.realm.com", "sess-001");
        assert!(result.is_ok());
    }
}
